<!doctype html><html><head><meta charset="utf-8"><style>
@page{margin:26px 32px}*{box-sizing:border-box}body{margin:0;font-family:DejaVu Sans,Arial,sans-serif;color:#20201d;font-size:10px}.invoice-document{border:1px solid #e6e2df}.invoice-doc-header{display:table;width:100%;padding:22px 26px;background:#0b0b0b;color:#fff}.invoice-doc-header>div{display:table-cell;vertical-align:middle}.invoice-doc-header>div:last-child{text-align:right}.invoice-doc-header img{width:98px}.invoice-doc-header span,.invoice-parties span,.invoice-milestone span,.invoice-bank span,.invoice-terms span,.invoice-note span{color:#ff4f12;font-size:8px;font-weight:bold;letter-spacing:1.3px}.invoice-doc-header h1{margin:4px 0;font-size:20px}.invoice-parties{display:table;width:100%;padding:22px 26px;border-bottom:1px solid #eee}.invoice-parties>div{display:table-cell;width:34%;vertical-align:top}.invoice-parties h2{margin:7px 0;font-size:13px}.invoice-parties p{margin:3px 0;color:#5f5b57}.invoice-meta dl,.invoice-totals dl{margin:0}.invoice-meta dt,.invoice-meta dd{display:inline-block;width:48%;margin:0 0 6px}.invoice-meta dt{color:#777}.invoice-meta dd{text-align:right;font-weight:bold}.invoice-milestone{margin:18px 26px 0;padding:13px 16px;background:#fff3ed;border-left:3px solid #ff4f12}.invoice-milestone h3{margin:5px 0;font-size:12px}.invoice-milestone p{margin:4px 0;color:#5d5551}.invoice-items{width:calc(100% - 52px);margin:18px 26px;border-collapse:collapse}.invoice-items th{text-align:left;padding:9px;border-bottom:2px solid #111;font-size:8px;letter-spacing:.7px}.invoice-items th:not(:first-child),.invoice-items td:not(:first-child){text-align:right}.invoice-items td{padding:10px 9px;border-bottom:1px solid #e8e5e2}.invoice-bottom{display:table;width:100%;padding:4px 26px 16px}.invoice-bottom>section,.invoice-bottom>aside{display:table-cell;width:50%;vertical-align:top}.invoice-bank,.invoice-terms{margin-right:25px;margin-bottom:14px}.invoice-bank h3{margin:6px 0}.invoice-bank p,.invoice-terms p{margin:3px 0;color:#5f5b57}.invoice-instructions{padding-top:6px}.invoice-totals{padding:10px 14px;background:#f6f4f2}.invoice-totals dt,.invoice-totals dd{display:inline-block;width:49%;padding:5px 0;margin:0}.invoice-totals dd{text-align:right;font-weight:bold}.invoice-totals .grand{border-top:1px solid #aaa;margin-top:3px;font-size:11px}.invoice-totals .balance{padding:8px 0;color:#ff4f12;font-size:12px}.invoice-note{margin:0 26px 12px;padding:10px;background:#faf9f7}.invoice-signature{display:table;width:100%;padding:14px 26px 20px}.invoice-signature>div,.invoice-signature>p{display:table-cell;width:50%;vertical-align:bottom}.invoice-signature>p{text-align:right;color:#777}.invoice-signature img{display:block;max-width:130px;max-height:52px}.signature-line{display:block;width:160px;border-top:1px solid #777;margin:5px 0}.invoice-signature strong,.invoice-signature small{display:block}
</style></head><body>@include('agency.invoice-document')</body></html>
